window.__rgjF=null; window.__rgjErr=null;
(async () => { try {
  const want = ["Punch-Out!!", "Duck Tales"];
  const alnum = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g,'');
  const toks  = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(' ').filter(Boolean);
  const isJunk = t => /^~|hack|subset|prototype|bootleg|unlicensed|translat|demake/i.test(String(t));
  const findAch = (n,d) => { if(!n||typeof n!=='object'||d>8) return null;
    if (Array.isArray(n)&&n.length&&n[0]&&typeof n[0]==='object'&&'title' in n[0]&&'points' in n[0]) return n;
    for (const k in n){ const r=findAch(n[k],d+1); if(r) return r; } return null; };
  const pick = (rows) => {
    const r = rows.filter(a => Number(a.points) > 0).sort((a,b)=> a.ratio-b.ratio || a.points-b.points || a.id-b.id);
    if (!r.length) return [];
    if (r.length <= 3) return r.map((x,i)=>({...x, tier:['easy','intermediate','advanced'][i]}));
    const easy=r[0], hard=r[r.length-1];
    const mid=Math.sqrt(Math.max(easy.ratio,1)*Math.max(hard.ratio,1));
    const dist=x=>Math.abs(Math.log(Math.max(x.ratio,1))-Math.log(mid));
    let m=r[1]; for (const x of r.slice(1,-1)) if (dist(x)<dist(m)) m=x;
    return [{...easy,tier:'easy'},{...m,tier:'intermediate'},{...hard,tier:'advanced'}];
  };
  const score = (q, cand) => {
    if (isJunk(cand)) return -1;
    if (alnum(q) === alnum(cand)) return 120;
    const ta = toks(q), tb = toks(cand);
    const hit = ta.filter(x => tb.includes(x)).length;
    let s = hit * 10;
    if (alnum(cand).startsWith(alnum(q)) || alnum(q).startsWith(alnum(cand))) s += 10;
    if (alnum(cand).includes(alnum(q)) && alnum(q).length > 4) s += 6;
    return s - Math.abs(ta.length - tb.length) - Math.max(0, tb.length - ta.length);
  };
  const out = {};
  for (const t of want) {
    let games = [];
    for (const q of [t, t.replace(/[^A-Za-z0-9 ]+/g,' ')]) {
      try {
        const j = await (await fetch('https://retroachievements.org/internal-api/search?q='+encodeURIComponent(q)+'&scope=games')).json();
        games = games.concat((j.results && j.results.games) || []);
      } catch(e) {}
      await new Promise(r=>setTimeout(r,150));
    }
    const seen = new Map();
    for (const g of games) if (g.system && g.system.id === 7 && !seen.has(g.id)) seen.set(g.id, g);
    let best = null, bs = 0;
    for (const g of seen.values()) { const s = score(t, g.title); if (s > bs) { bs = s; best = g; } }
    if (!best || bs < 14) { out[t] = { unmatched: true, near: [...seen.values()].map(g=>g.title).slice(0,8) }; continue; }
    try {
      const h = await (await fetch('https://retroachievements.org/game/'+best.id)).text();
      const j2 = JSON.parse(new DOMParser().parseFromString(h,'text/html').querySelector('script[type="application/json"]').textContent);
      const rows = (findAch(j2,0)||[]).map(a => ({ id:a.id, title:a.title, desc:a.description||'', points:Number(a.points)||0,
                                   ratio:Number(a.pointsWeighted)||Number(a.points)||0, type:a.type||'' }));
      out[t] = { raId: best.id, raTitle: best.title, n: rows.length, matchScore: bs, picks: pick(rows), unmatched: false };
    } catch(e) { out[t] = { raId: best.id, raTitle: best.title, error: String(e.message), picks: [] }; }
    await new Promise(r=>setTimeout(r,150));
  }
  window.__rgjF = JSON.stringify(out);
} catch(e){ window.__rgjErr = String(e && e.stack || e); } })();
